WITH valid_shipments AS (SELECT *, CEIL(cost) AS cost_whole FROM shipments WHERE delivered_date > '2025-01-01'), carrier_summary AS (SELECT carrier, CASE WHEN carrier IN ('Kerry', 'UPS') THEN 'core' ELSE 'other' END AS carrier_group, COUNT(CASE WHEN carrier = 'Flash' THEN 1 END) AS flash_count, COUNT(*) AS shipment_count FROM valid_shipments GROUP BY carrier, CASE WHEN carrier IN ('Kerry', 'UPS') THEN 'core' ELSE 'other' END) SELECT * FROM carrier_summary ORDER BY flash_count, carrier
